-- An exact approved inverse restores previously booked failed-refund funds.
-- It is not a new customer deposit,invoice receipt,provider call or bank proof.
CREATE TABLE public.provider_refund_returns(
 academy_id uuid NOT NULL,id uuid NOT NULL,refund_posting_id uuid NOT NULL,collection_id uuid NOT NULL,return_inspection_id uuid NOT NULL,posted_on date NOT NULL,
 amount_minor numeric NOT NULL CHECK(amount_minor>0 AND amount_minor=trunc(amount_minor)),source jsonb NOT NULL,approval_id uuid NOT NULL,created_by uuid NOT NULL,reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(academy_id,id),UNIQUE(academy_id,refund_posting_id),
 FOREIGN KEY(academy_id,refund_posting_id) REFERENCES public.provider_refund_postings(academy_id,id),FOREIGN KEY(academy_id,collection_id) REFERENCES public.provider_collections(academy_id,id),FOREIGN KEY(academy_id,return_inspection_id) REFERENCES public.checkout_refund_return_inspections(academy_id,id),
 FOREIGN KEY(academy_id,approval_id) REFERENCES public.approval_requests(academy_id,id),FOREIGN KEY(academy_id,created_by) REFERENCES public.people(academy_id,id),FOREIGN KEY(academy_id,id) REFERENCES public.finance_journals(academy_id,id) DEFERRABLE INITIALLY DEFERRED
);
ALTER TABLE public.provider_refund_returns ENABLE ROW LEVEL SECURITY;ALTER TABLE public.provider_refund_returns FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_boundary ON public.provider_refund_returns USING(academy_id=nullif(current_setting('app.academy_id',true),'')::uuid) WITH CHECK(academy_id=nullif(current_setting('app.academy_id',true),'')::uuid);
CREATE TRIGGER finance_book_write BEFORE INSERT OR UPDATE OR DELETE ON public.provider_refund_returns FOR EACH STATEMENT EXECUTE FUNCTION public.guard_finance_book_write();
GRANT SELECT,INSERT ON public.provider_refund_returns TO kavosh_runtime;
CREATE FUNCTION public.provider_refund_return_source(p_posting uuid,p_inspection uuid,p_on date) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog SET DateStyle='ISO,YMD' AS $$
DECLARE p record;c record;e record;latest record;r jsonb;original_refund jsonb;history jsonb;minor numeric;BEGIN
 SELECT * INTO p FROM public.provider_refund_postings WHERE id=p_posting;
 SELECT pc.*,q.currency_code,q.unit_scale,cl.time_zone INTO c FROM public.provider_collections pc JOIN public.payment_checkout_dispatch_starts st ON st.academy_id=pc.academy_id AND st.id=pc.start_id JOIN public.payment_checkout_attempts a ON a.academy_id=st.academy_id AND a.id=st.attempt_id JOIN public.payment_checkout_requests q ON q.academy_id=a.academy_id AND q.id=a.request_id JOIN public.classes cl ON cl.academy_id=pc.academy_id AND cl.id=pc.class_id WHERE pc.academy_id=p.academy_id AND pc.id=p.collection_id;
 SELECT * INTO e FROM public.checkout_refund_return_inspections WHERE academy_id=p.academy_id AND id=p_inspection AND start_id=c.start_id AND refund_id=p.refund_id;
 IF p.id IS NULL OR c.id IS NULL OR e.id IS NULL OR e.object_conflict OR e.return_inspection->>'state' IS DISTINCT FROM 'return_balance' OR e.return_inspection->'requiresManualReview' IS DISTINCT FROM 'false'::jsonb OR e.return_inspection->>'refundStatus' NOT IN('failed','canceled') OR e.return_inspection->>'chargeId' IS DISTINCT FROM c.charge_id OR e.return_inspection->>'currency' IS DISTINCT FROM lower(c.currency_code) OR p_on IS NULL OR p_on NOT BETWEEN DATE '0001-01-01' AND DATE '9999-12-31' OR p_on<p.posted_on OR p_on<(to_timestamp((e.return_inspection->>'createdAt')::double precision) AT TIME ZONE c.time_zone)::date THEN RETURN NULL;END IF;
 minor=(e.return_inspection->>'grossAmount')::numeric*power(10::numeric,c.unit_scale)/power(10::numeric,(e.return_inspection->>'providerUnitScale')::integer);IF minor IS DISTINCT FROM p.amount_minor THEN RETURN NULL;END IF;
 SELECT v.value INTO original_refund FROM public.checkout_refund_inspections i CROSS JOIN LATERAL jsonb_array_elements(i.refund_inspection->'refunds') v WHERE i.academy_id=p.academy_id AND i.id=p.inspection_id AND v.value->>'id'=p.refund_id;
 IF original_refund IS NULL OR original_refund->'createdAt' IS DISTINCT FROM e.return_inspection->'refundCreatedAt' OR original_refund->'amount' IS DISTINCT FROM e.return_inspection->'refundAmount' OR original_refund->'currency' IS DISTINCT FROM e.return_inspection->'refundCurrency' OR(original_refund->>'balanceTransactionId' IS NOT NULL AND original_refund->'balanceTransactionId' IS DISTINCT FROM e.return_inspection->'originalBalanceTransactionId') THEN RETURN NULL;END IF;
 SELECT inspection INTO latest FROM public.checkout_provider_inspections WHERE academy_id=p.academy_id AND start_id=c.start_id ORDER BY received_at DESC,id DESC LIMIT 1;
 IF latest.inspection IS NULL OR latest.inspection->>'state' NOT IN('captured','requires_review') OR latest.inspection->>'chargeId' IS DISTINCT FROM c.charge_id OR latest.inspection->>'currency' IS DISTINCT FROM lower(c.currency_code) OR NOT EXISTS(SELECT 1 FROM public.checkout_provider_inspections original WHERE original.academy_id=c.academy_id AND original.id=c.inspection_id AND original.inspection->'amount'=latest.inspection->'amount') THEN RETURN NULL;END IF;
 SELECT * INTO latest FROM public.checkout_refund_return_inspections WHERE academy_id=p.academy_id AND start_id=c.start_id AND refund_id=p.refund_id ORDER BY received_at DESC,id DESC LIMIT 1;
 IF latest.object_conflict OR latest.return_inspection IS DISTINCT FROM e.return_inspection THEN RETURN NULL;END IF;
 SELECT v.value INTO r FROM public.checkout_refund_inspections i CROSS JOIN LATERAL jsonb_array_elements(i.refund_inspection->'refunds') v WHERE i.academy_id=p.academy_id AND i.start_id=c.start_id AND v.value->>'id'=p.refund_id ORDER BY i.received_at DESC,i.id DESC LIMIT 1;
 IF r IS NULL OR r->'status' IS DISTINCT FROM e.return_inspection->'refundStatus' OR r->'balanceTransactionId' IS DISTINCT FROM e.return_inspection->'originalBalanceTransactionId' OR r->'failureBalanceTransactionId' IS DISTINCT FROM e.return_inspection->'balanceTransactionId' OR r->'amount' IS DISTINCT FROM e.return_inspection->'refundAmount' OR r->'currency' IS DISTINCT FROM e.return_inspection->'refundCurrency' OR r->'createdAt' IS DISTINCT FROM e.return_inspection->'refundCreatedAt'
 OR EXISTS(SELECT 1 FROM public.checkout_provider_inspections bad WHERE bad.academy_id=p.academy_id AND bad.start_id=c.start_id AND(bad.object_conflict OR bad.inspection->'disputed'='true'::jsonb))
 OR EXISTS(SELECT 1 FROM public.checkout_refund_inspections bad WHERE bad.academy_id=p.academy_id AND bad.start_id=c.start_id AND bad.object_conflict)
 OR EXISTS(SELECT 1 FROM public.checkout_refund_return_inspections bad JOIN public.payment_checkout_dispatch_starts st ON st.academy_id=bad.academy_id AND st.id=bad.start_id JOIN public.payment_checkout_attempts a ON a.academy_id=st.academy_id AND a.id=st.attempt_id WHERE bad.academy_id=p.academy_id AND bad.object_conflict AND a.draft->>'accountId'=p.account_id AND(a.draft->>'livemode')::boolean=p.livemode AND(bad.start_id=c.start_id OR bad.return_inspection->>'balanceTransactionId'=e.return_inspection->>'balanceTransactionId'))
 OR EXISTS(SELECT 1 FROM public.checkout_fee_inspections bad JOIN public.payment_checkout_dispatch_starts st ON st.academy_id=bad.academy_id AND st.id=bad.start_id JOIN public.payment_checkout_attempts a ON a.academy_id=st.academy_id AND a.id=st.attempt_id WHERE bad.academy_id=p.academy_id AND bad.object_conflict AND a.draft->>'accountId'=p.account_id AND(a.draft->>'livemode')::boolean=p.livemode AND bad.fee_inspection->>'balanceTransactionId'=e.return_inspection->>'balanceTransactionId')
 OR NOT EXISTS(SELECT 1 FROM public.checkout_refund_return_bindings b WHERE b.academy_id=p.academy_id AND b.account_id=p.account_id AND b.livemode=p.livemode AND b.transaction_id=e.return_inspection->>'balanceTransactionId' AND b.start_id=c.start_id AND b.refund_id=p.refund_id AND b.amount=(e.return_inspection->>'grossAmount')::numeric AND b.currency=e.return_inspection->>'currency') THEN RETURN NULL;END IF;
 -- Ordered transitions stop an older response resurrecting an earlier approval.
 WITH facts AS(
  SELECT 'provider' stream,i.received_at,i.id,i.inspection fact FROM public.checkout_provider_inspections i WHERE i.academy_id=p.academy_id AND i.start_id=c.start_id
  UNION ALL SELECT 'refund',i.received_at,i.id,v.value FROM public.checkout_refund_inspections i CROSS JOIN LATERAL jsonb_array_elements(i.refund_inspection->'refunds') v WHERE i.academy_id=p.academy_id AND i.start_id=c.start_id AND v.value->>'id'=p.refund_id
  UNION ALL SELECT 'return',i.received_at,i.id,i.return_inspection FROM public.checkout_refund_return_inspections i WHERE i.academy_id=p.academy_id AND i.start_id=c.start_id AND i.refund_id=p.refund_id
 ),transitions AS(SELECT *,lag(fact) OVER(PARTITION BY stream ORDER BY received_at,id) prior FROM facts)
 SELECT coalesce(jsonb_agg(jsonb_build_array(stream,fact) ORDER BY stream,received_at,id) FILTER(WHERE fact IS DISTINCT FROM prior),'[]'::jsonb) INTO history FROM transitions;
 RETURN jsonb_build_object('refundPostingId',p.id,'collectionId',c.id,'returnInspectionId',e.id,'refundId',p.refund_id,'amountMinor',p.amount_minor::text,'currencyCode',c.currency_code,'unitScale',c.unit_scale,'postedOn',p_on::text,'originalPostedOn',p.posted_on::text,'alreadyReturned',EXISTS(SELECT 1 FROM public.provider_refund_returns x WHERE x.academy_id=p.academy_id AND x.refund_posting_id=p.id),'historyStamp',encode(sha256(convert_to(history::text,'UTF8')),'hex'),'evidence',e.return_inspection,'bankSettlementVerified',false,'providerOperationPerformed',false);
END $$;
CREATE FUNCTION public.guard_provider_refund_return() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE c record;p record;s jsonb;BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'PROVIDER_REFUND_RETURN_IMMUTABLE' USING ERRCODE='23514';END IF;
 SELECT * INTO c FROM public.provider_collections WHERE academy_id=NEW.academy_id AND id=NEW.collection_id;
 PERFORM public.lock_customer_credit(NEW.collection_id);PERFORM public.lock_collector_funds(c.collector_id,c.holding_account);PERFORM id FROM public.tuition_invoices WHERE academy_id=NEW.academy_id AND id=c.invoice_id FOR UPDATE;
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.academy_id::text||':checkout-provider:'||c.account_id,0));
 s=public.provider_refund_return_source(NEW.refund_posting_id,NEW.return_inspection_id,NEW.posted_on);SELECT * INTO p FROM public.approval_requests WHERE academy_id=NEW.academy_id AND id=NEW.approval_id;
 IF s IS NULL OR s->'alreadyReturned' IS DISTINCT FROM 'false'::jsonb OR NEW.source IS DISTINCT FROM s OR NEW.collection_id IS DISTINCT FROM(s->>'collectionId')::uuid OR NEW.amount_minor IS DISTINCT FROM(s->>'amountMinor')::numeric
 OR p.id IS NULL OR p.action IS DISTINCT FROM 'finance.provider-refund.return' OR p.status IS DISTINCT FROM 'pending' OR p.target_id IS DISTINCT FROM NEW.id OR p.target_version<>0 OR p.privacy_capability IS DISTINCT FROM 'receipts.edit' OR p.review_context->'source' IS DISTINCT FROM s
 OR p.payload IS DISTINCT FROM jsonb_build_object('refundPostingId',NEW.refund_posting_id,'collectionId',NEW.collection_id,'returnInspectionId',NEW.return_inspection_id,'postedOn',NEW.posted_on::text,'period',p.payload->'period','reason',NEW.reason)
 OR p.scope->'recordContext' IS DISTINCT FROM jsonb_build_object('hubId',c.hub_id,'classId',c.class_id,'studentId',c.student_id) OR NOT public.report_comment_human_verified(NEW.created_by) OR NOT EXISTS(SELECT 1 FROM public.academies WHERE id=NEW.academy_id AND status='active') THEN RAISE EXCEPTION 'PROVIDER_REFUND_RETURN_SOURCE_OR_REVIEW_INVALID' USING ERRCODE='23514';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.academies WHERE id=NEW.academy_id AND master_person_id=NEW.created_by) AND(p.requester_id=NEW.created_by OR c.student_id=NEW.created_by OR EXISTS(SELECT 1 FROM public.family_relationships WHERE academy_id=NEW.academy_id AND student_id=c.student_id AND guardian_id=NEW.created_by) OR EXISTS(SELECT 1 FROM public.finance_collectors WHERE academy_id=NEW.academy_id AND id=c.collector_id AND person_id=NEW.created_by)) THEN RAISE EXCEPTION 'PROVIDER_REFUND_RETURN_UPPER_REVIEW_REQUIRED' USING ERRCODE='23514';END IF;
 NEW.created_at=transaction_timestamp();RETURN NEW;
END $$;
CREATE TRIGGER provider_refund_return BEFORE INSERT OR UPDATE OR DELETE ON public.provider_refund_returns FOR EACH ROW EXECUTE FUNCTION public.guard_provider_refund_return();
CREATE FUNCTION public.complete_provider_refund_return() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE c record;p record;j record;BEGIN
 SELECT * INTO c FROM public.provider_collections WHERE academy_id=NEW.academy_id AND id=NEW.collection_id;SELECT * INTO p FROM public.approval_requests WHERE academy_id=NEW.academy_id AND id=NEW.approval_id;SELECT * INTO j FROM public.finance_journals WHERE academy_id=NEW.academy_id AND id=NEW.id;
 IF p.status IS DISTINCT FROM 'applied' OR p.reviewer_id IS DISTINCT FROM NEW.created_by OR j.id IS NULL OR j.approval_id IS DISTINCT FROM NEW.approval_id OR j.posted_by IS DISTINCT FROM NEW.created_by OR j.posted_on IS DISTINCT FROM NEW.posted_on OR j.reverses_id IS DISTINCT FROM NEW.refund_posting_id OR j.line_count<>2 OR j.reference IS DISTINCT FROM 'provider-refund-return:'||NEW.id::text
 OR j.period_id IS DISTINCT FROM(p.payload#>>'{period,id}')::uuid OR j.period_version IS DISTINCT FROM(p.payload#>>'{period,version}')::integer
 OR NOT EXISTS(SELECT 1 FROM public.finance_journal_lines WHERE academy_id=NEW.academy_id AND journal_id=NEW.id AND line_number=1 AND account_id=c.credit_account AND side='credit' AND amount_minor=NEW.amount_minor)
 OR NOT EXISTS(SELECT 1 FROM public.finance_journal_lines WHERE academy_id=NEW.academy_id AND journal_id=NEW.id AND line_number=2 AND account_id=c.holding_account AND side='debit' AND amount_minor=NEW.amount_minor)
 OR NOT EXISTS(SELECT 1 FROM public.audit_events WHERE academy_id=NEW.academy_id AND entity_id=NEW.id AND actor_id=NEW.created_by AND created_at=transaction_timestamp() AND action='finance.provider-refund.returned' AND changes=jsonb_build_object('approvalId',NEW.approval_id,'collectionId',NEW.collection_id,'refundPostingId',NEW.refund_posting_id,'severity','critical','providerOperationPerformed',false,'bankSettled',false)) THEN RAISE EXCEPTION 'PROVIDER_REFUND_RETURN_INCOMPLETE' USING ERRCODE='23514';END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER provider_refund_return_complete AFTER INSERT ON public.provider_refund_returns DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.complete_provider_refund_return();
CREATE FUNCTION public.provider_refund_return_effect() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF NEW.status='applied' AND NEW.action='finance.provider-refund.return' AND NOT EXISTS(SELECT 1 FROM public.provider_refund_returns WHERE academy_id=NEW.academy_id AND id=NEW.target_id AND approval_id=NEW.id AND created_by=NEW.reviewer_id) THEN RAISE EXCEPTION 'PROVIDER_REFUND_RETURN_EFFECT_REQUIRED' USING ERRCODE='23514';END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER provider_refund_return_effect AFTER INSERT OR UPDATE ON public.approval_requests DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.provider_refund_return_effect();
CREATE TRIGGER zz_provider_refund_return_privacy BEFORE INSERT ON public.approval_requests FOR EACH ROW WHEN(NEW.action='finance.provider-refund.return') EXECUTE FUNCTION public.provider_refund_privacy();
DO $$ DECLARE d text;needle text;BEGIN
 d=pg_get_functiondef('public.checkout_notice_current(uuid)'::regprocedure);needle='NOT IN(''provider'',''refunds'')';IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'REFUND_RETURN_NOTICE_CURRENT_CHANGED';END IF;EXECUTE replace(d,needle,'NOT IN(''provider'',''refunds'',''refund_return'')');
 d=pg_get_functiondef('public.provider_refund_journal_guard()'::regprocedure);needle='THEN RAISE EXCEPTION ''PROVIDER_REFUND_CORRECTION_WORKFLOW_REQUIRED''';
 IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'REFUND_RETURN_JOURNAL_GUARD_CHANGED';END IF;
 EXECUTE replace(d,needle,'AND NOT EXISTS(SELECT 1 FROM public.provider_refund_returns r WHERE r.academy_id=NEW.academy_id AND r.id=NEW.id AND r.refund_posting_id=NEW.reverses_id AND r.approval_id=NEW.approval_id) '||needle);
 d=pg_get_functiondef('public.customer_credit_reservation_usage(uuid,uuid,uuid,date)'::regprocedure);needle='),invoice_events AS MATERIALIZED(';IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'REFUND_RETURN_CREDIT_USAGE_CHANGED';END IF;
 EXECUTE replace(d,needle,' UNION ALL SELECT r.posted_on,-r.amount_minor FROM public.provider_refund_returns r WHERE r.academy_id=p_academy AND r.collection_id=p_collection '||needle);
 d=pg_get_viewdef('public.collector_fund_events'::regclass,true);EXECUTE 'CREATE OR REPLACE VIEW public.collector_fund_events WITH(security_invoker=true) AS '||rtrim(d,E';\n ')||' UNION ALL SELECT r.academy_id,c.collector_id,c.holding_account,r.id,r.posted_on,r.amount_minor FROM public.provider_refund_returns r JOIN public.provider_collections c ON c.academy_id=r.academy_id AND c.id=r.collection_id';
 d=pg_get_functiondef('public.provider_collection_accounting_summary(uuid,date)'::regprocedure);needle='), totals AS (';IF strpos(d,needle)=0 THEN needle='),totals AS(';END IF;IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'REFUND_RETURN_SUMMARY_CHANGED';END IF;
 EXECUTE replace(d,needle,' UNION ALL SELECT r.posted_on,-r.amount_minor FROM c JOIN public.provider_refund_returns r ON r.academy_id=c.academy_id AND r.collection_id=c.id '||needle);
 -- A returned failed refund is no longer an outstanding withdrawal,while the
 -- original booking remains retained and the correction date gates reuse.
 d=pg_get_functiondef('public.provider_credit_review_basis(uuid,uuid[])'::regprocedure);
 needle='FROM public.provider_refund_postings p WHERE p.academy_id=c.academy_id AND p.collection_id=c.id;';
 IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'REFUND_RETURN_REVIEW_BOOKINGS_CHANGED';END IF;
 d=replace(d,needle,'FROM public.provider_refund_postings p WHERE p.academy_id=c.academy_id AND p.collection_id=c.id AND NOT EXISTS(SELECT 1 FROM public.provider_refund_returns x WHERE x.academy_id=p.academy_id AND x.refund_posting_id=p.id);');
 needle='-- Keep ordered material transitions';IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'REFUND_RETURN_REVIEW_DATE_CHANGED';END IF;
 d=replace(d,needle,'SELECT greatest(safe_on,coalesce(max(x.posted_on),safe_on)) INTO safe_on FROM public.provider_refund_returns x WHERE x.academy_id=c.academy_id AND x.collection_id=c.id;'||E'\n '||needle);EXECUTE d;
END $$;
REVOKE ALL ON FUNCTION public.provider_refund_return_source(uuid,uuid,date),public.guard_provider_refund_return(),public.complete_provider_refund_return(),public.provider_refund_return_effect() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.provider_refund_return_source(uuid,uuid,date) TO kavosh_runtime;
CREATE OR REPLACE FUNCTION public.schema_revision() RETURNS integer LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT 308 $$;
